// src/modules/mem/register.ts
function toHandle2(name, reg) {
  return {
    name,
    enable: () => reg.enable(),
    disable: () => reg.disable()
  };
}
function registerMemModule(server, opts, uiResourceUri) {
  const rootDataDir = resolveNovDataDir(opts.dataDir);
  const dataDir = getModuleDataDir(rootDataDir, "mem");
  const store = new MemoryStore(dataDir, Boolean(opts.demoMode), opts.workspaceRoot);
  const APP_ONLY_META2 = {
    ui: {
      resourceUri: uiResourceUri,
      visibility: ["app"]
    }
  };
  const buildPayload = () => {
    const memories = store.list();
    return {
      memories,
      graph: buildMemoryGraph(memories),
      injectionPreview: store.buildSessionStartInjection()
    };
  };
  const modelTools = [];
  const rememberTool = server.registerTool(
    "mem_remember",
    {
      title: "Remember Code-Anchored Fact",
      description: "Store a long-term architectural decision, pitfall, convention, or preference anchored to source file paths (with SHA-256 drift tracking).",
      inputSchema: {
        kind: external_exports.enum(["architecture", "decision", "pitfall", "convention", "preference"]),
        title: external_exports.string().min(2),
        content: external_exports.string().min(4),
        tags: external_exports.array(external_exports.string()).optional(),
        workspacePath: external_exports.string().optional(),
        anchors: external_exports.array(external_exports.object({ filePath: external_exports.string(), symbol: external_exports.string().optional() })).optional(),
        pinned: external_exports.boolean().optional()
      }
    },
    async (input2) => {
      const saved = store.remember(input2);
      return {
        content: [
          {
            type: "text",
            text: `Remembered [${saved.kind.toUpperCase()}] "${saved.title}" (id=${saved.id}, anchors=${saved.anchors.length}, pinned=${saved.pinned}).`
          }
        ],
        structuredContent: {
          id: saved.id,
          kind: saved.kind,
          title: saved.title,
          pinned: saved.pinned,
          drifted: Boolean(saved.drifted),
          anchorCount: saved.anchors.length,
          tagCount: saved.tags.length,
          updatedAt: saved.updatedAt
        }
      };
    }
  );
  modelTools.push(toHandle2("mem_remember", rememberTool));
  const recallTool = server.registerTool(
    "mem_recall",
    {
      title: "Recall Long-Term Memories",
      description: "Search saved long-term memories using local bilingual (EN + \u4E2D\u6587) BM25 ranking.",
      inputSchema: {
        query: external_exports.string(),
        workspacePath: external_exports.string().optional(),
        limit: external_exports.number().int().min(1).max(30).optional()
      }
    },
    async ({ query, workspacePath, limit }) => {
      const hits = store.recall(query, { workspacePath, limit: limit ?? 8, incrementRecall: true });
      const text = hits.length ? hits.map(
        (m, i) => `${i + 1}. [${m.kind.toUpperCase()}${m.drifted ? " \xB7 DRIFTED" : ""}] ${m.title} (score ${m.score})
   ${m.content}`
      ).join("\n") : `No memories matched "${query}".`;
      return {
        content: [{ type: "text", text }],
        structuredContent: {
          query,
          totalHits: hits.length,
          matches: hits.map((m) => ({
            id: m.id,
            kind: m.kind,
            title: m.title,
            score: m.score,
            pinned: m.pinned,
            drifted: Boolean(m.drifted),
            anchorCount: m.anchors.length,
            tagCount: m.tags.length
          }))
        }
      };
    }
  );
  modelTools.push(toHandle2("mem_recall", recallTool));
  const forgetTool = server.registerTool(
    "mem_forget",
    {
      title: "Forget Memory",
      description: "Permanently delete a memory by its ID.",
      inputSchema: { id: external_exports.string().min(1) }
    },
    async ({ id }) => {
      const ok = store.forget(id);
      return {
        content: [{ type: "text", text: ok ? `Deleted memory ${id}.` : `Memory ${id} not found.` }],
        structuredContent: { deleted: ok, id }
      };
    }
  );
  modelTools.push(toHandle2("mem_forget", forgetTool));
  server.registerTool(
    "app_mem_get_state",
    {
      title: "Get Memory State (App Only)",
      description: "Fetch memories, graph & injection preview.",
      inputSchema: {},
      _meta: APP_ONLY_META2
    },
    async () => ({
      content: [{ type: "text", text: "ok" }],
      structuredContent: buildPayload()
    })
  );
  server.registerTool(
    "app_mem_search",
    {
      title: "Search Memories (App Only)",
      description: "Interactive bilingual search from UI.",
      inputSchema: { query: external_exports.string() },
      _meta: APP_ONLY_META2
    },
    async ({ query }) => ({
      content: [{ type: "text", text: "ok" }],
      structuredContent: { hits: store.recall(query, { limit: 25 }) }
    })
  );
  server.registerTool(
    "app_mem_add_memory",
    {
      title: "Add Memory (App Only)",
      description: "Create or update a memory card from UI.",
      inputSchema: {
        kind: external_exports.enum(["architecture", "decision", "pitfall", "convention", "preference"]),
        title: external_exports.string().min(2),
        content: external_exports.string().min(4),
        tags: external_exports.array(external_exports.string()).optional(),
        anchorFiles: external_exports.array(external_exports.string()).optional(),
        pinned: external_exports.boolean().optional()
      },
      _meta: APP_ONLY_META2
    },
    async (input2) => {
      store.remember({
        kind: input2.kind,
        title: input2.title,
        content: input2.content,
        tags: input2.tags,
        anchors: (input2.anchorFiles ?? []).filter(Boolean).map((filePath) => ({ filePath })),
        pinned: input2.pinned
      });
      return {
        content: [{ type: "text", text: "saved" }],
        structuredContent: buildPayload()
      };
    }
  );
  server.registerTool(
    "app_mem_toggle_pin",
    {
      title: "Toggle Pin (App Only)",
      description: "Pin or unpin a memory for SessionStart recall.",
      inputSchema: { id: external_exports.string() },
      _meta: APP_ONLY_META2
    },
    async ({ id }) => {
      store.togglePin(id);
      return {
        content: [{ type: "text", text: "toggled" }],
        structuredContent: buildPayload()
      };
    }
  );
  server.registerTool(
    "app_mem_reverify_drift",
    {
      title: "Reverify Anchor Hashes (App Only)",
      description: "Refresh SHA-256 anchor hashes after confirming a drifted memory is still accurate.",
      inputSchema: { id: external_exports.string() },
      _meta: APP_ONLY_META2
    },
    async ({ id }) => {
      store.reverifyAnchorHashes(id);
      return {
        content: [{ type: "text", text: "reverified" }],
        structuredContent: buildPayload()
      };
    }
  );
  server.registerTool(
    "app_mem_delete_memory",
    {
      title: "Delete Memory (App Only)",
      description: "Delete a memory card from UI.",
      inputSchema: { id: external_exports.string() },
      _meta: APP_ONLY_META2
    },
    async ({ id }) => {
      store.forget(id);
      return {
        content: [{ type: "text", text: "deleted" }],
        structuredContent: buildPayload()
      };
    }
  );
  return {
    moduleId: "mem",
    modelTools
  };
}

